ReplacementContent:
"                  <select
                    value={`${transportStartDate}|${selectedTransportDays}`}
                    onChange={(e) => {
                      const [sDate, daysStr] = e.target.value.split("|");
                      updateField(service.id, "serviceDate", sDate);
                      updateField(service.id, "days", Number(daysStr));
                    }}
                    className={selectCls}
                  >
                    {allTransportRangeOptions.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>"

TargetContent:
"                  <select
                    value={selectedTransportDays}
                    onChange={(e) => updateField(service.id, "days", Number(e.target.value))}
                    className={selectCls}
                  >
                    {[...Array(maxTransportDays)].map((_, i) => (
                      <option key={i} value={i + 1}>
                        {i + 1} Day{i > 0 ? "s" : ""}
                        {transportStartDate
                          ? ` (${formatDisplayDate(transportStartDate)}${i > 0 ? ` → ${formatDisplayDate(addDaysToServiceDate(transportStartDate, i))}` : ""})`
                          : ""}
                      </option>
                    ))}
                  </select>"
